\section{Introduction}

\subsection{The measurement}

An experiment repeatedly reports a rank correlation between a structural
statistic $T$ of a uniformly drawn integer (the number of trailing zeros in its
binary expansion) and a downstream quantity called the \emph{rate}. Reported
over a sweep of increasing bit lengths, the readings form a \emph{ladder}:
\[
0.5739,\quad 0.5436,\quad 0.5005,\quad 0.4880,\quad 0.4621,\quad (0.4847),
\quad 0.43636 .
\]
The parenthesised rung is a \emph{rebound}: a step of $+0.0226$ against an
otherwise monotone decline. The final rung retraces it and overshoots, a step of
$-0.0483$, landing at $0.43636$ with confidence interval $[0.38815, 0.48113]$.
The seed-to-seed spread has widened to $0.082$. The statistic $T$ outperforms a
plain count baseline by $+0.0752$ at the point estimate; the baseline reads
$0.36116$.

Three interpretive questions attach to these numbers.
\begin{itemize}
\item \textbf{(Q1)} Is the rebound signal or noise?
\item \textbf{(Q2)} Is the decline an artefact of pooling heterogeneous seeds?
\item \textbf{(Q3)} Is there a positive floor below which the ladder cannot fall?
\end{itemize}

\subsection{What we supply}

Each question presupposes an understanding of what a pooled correlation is as a
geometric object. The pooled value is the correlation of \emph{concatenated}
vectors, and concatenation is not an averaging operation. We supply the missing
layer and answer Q1--Q3 with exact inequalities together with their sharpness,
rigidity and stability statements. The unifying result is
\emph{capacity--fade duality} (Section~\ref{sec:cap}): the fade hypothesis and
the floor hypothesis are logical complements.

\subsection{Notation}

Vectors live in $\mathbb{R}^n$, $\ip{u}{v} = \sum_i u_iv_i$,
$\norm{u} = \sqrt{\ip{u}{u}}$, and for nonzero $u,v$,
$\cor(u,v) = \ip{u}{v}/(\norm{u}\norm{v}) \in [-1,1]$. A \emph{block family} is
a tuple $u = (u_1,\dots,u_m)$ with $u_k \in \mathbb{R}^n$, representing the
per-seed data of an $m$-seed experiment. Write $E(u) = \sum_k \norm{u_k}^2$ for
the block energy and $\ip{u}{v}_{\mathrm{blk}} = \sum_k \ip{u_k}{v_k}$.

\section{Pooling geometry}

\begin{definition}[Pooled correlation]
For block families $u,v$ with $E(u), E(v) > 0$,
\[
\rpool(u,v) \;=\; \frac{\ip{u}{v}_{\mathrm{blk}}}{\sqrt{E(u)}\sqrt{E(v)}}
\;=\; \frac{\sum_k \ip{u_k}{v_k}}
{\sqrt{\sum_k \norm{u_k}^2}\;\sqrt{\sum_k\norm{v_k}^2}} ,
\]
the correlation of the concatenated vectors. Write $\rho_k = \cor(u_k,v_k)$.
\end{definition}

\begin{lemma}[Block Cauchy--Schwarz]\label{lem:bcs}
For $a_k, b_k \ge 0$, $\sum_k \sqrt{a_k}\sqrt{b_k} \le
\sqrt{\sum_k a_k}\sqrt{\sum_k b_k}$.
\end{lemma}

\begin{proof}
Cauchy--Schwarz applied to $(\sqrt{a_k})_k$ and $(\sqrt{b_k})_k$, using
$(\sqrt{a_k})^2 = a_k$.
\end{proof}

\begin{theorem}[Blockwise bounds transfer]\label{thm:transfer}
If $R \ge 0$ and $\ip{u_k}{v_k} \le R\norm{u_k}\norm{v_k}$ for all $k$, then
$\rpool(u,v) \le R$.
\end{theorem}

\begin{proof}
Summing gives $\ip{u}{v}_{\mathrm{blk}} \le R\sum_k \norm{u_k}\norm{v_k}$, and
Lemma~\ref{lem:bcs} with $a_k = \norm{u_k}^2$, $b_k = \norm{v_k}^2$ bounds the
sum by $\sqrt{E(u)}\sqrt{E(v)}$.
\end{proof}

\begin{corollary}[Pooling never inflates]\label{cor:noinfl}
If $\rho_k \le R$ for all $k$ with $R \ge 0$, then $\rpool(u,v) \le R$; in
particular $\rpool \le \max_k \rho_k$.
\end{corollary}

Thus a pooled dial value is a \emph{lower-bound witness} for the seed family: it
can never be an upward artefact of concatenation. The matching lower bound by
the seed minimum is false.

\begin{theorem}[Strict attenuation]\label{thm:atten}
There is a two-block family in $\mathbb{R}^1$ whose per-seed readings are both
exactly $1$ and whose pooled reading is $3/\sqrt{10} < 1$.
\end{theorem}

\begin{proof}
Take $u_1 = u_2 = (1)$, $v_1 = (1)$, $v_2 = (2)$. Each block reads $1$, while
$\rpool = 3/(\sqrt{2}\sqrt{5}) = 3/\sqrt{10} \approx 0.94868$.
\end{proof}

\begin{definition}[Balance]
The \emph{ratio profile} of $(u,v)$ is $\lambda_k = \norm{v_k}/\norm{u_k}$; the
pair is \emph{$\lambda$-balanced} if all $\lambda_k$ equal a common $\lambda>0$.
\end{definition}

\begin{theorem}[Balanced pooling is a weighted average]\label{thm:bal}
If $(u,v)$ is $\lambda$-balanced and $E(u)>0$, then
\[
\rpool(u,v) = \frac{\sum_k \norm{u_k}^2 \rho_k}{\sum_k \norm{u_k}^2}.
\]
\end{theorem}

\begin{proof}
Balance gives $\ip{u_k}{v_k} = \lambda \rho_k \norm{u_k}^2$ and
$E(v) = \lambda^2 E(u)$; the factor $\lambda$ cancels.
\end{proof}

\begin{corollary}[Balanced sandwich]\label{cor:sandwich}
For a $\lambda$-balanced pair with all $\rho_k \in [\ell,h]$ we have
$\rpool \in [\ell,h]$.
\end{corollary}

The whole discrepancy between pooling and averaging is caused by the spread of
the ratio profile. A first, unsharp bound: if all $\rho_k \ge \rho \ge 0$ and
$\lambda_k \in [L(1-\delta), L(1+\delta)]$ with $0 \le \delta < 1$, then
$\rpool \ge \rho(1-\delta)/(1+\delta)$. Because it is unsharp it cannot say how
much of an observed fall imbalance is \emph{allowed} to explain; the next section
replaces it.

\section{The sharp seed-imbalance law}

\begin{theorem}[Weighted Kantorovich inequality]\label{thm:kant}
Let $w_k \ge 0$ and $\lambda_k \in [\alpha,\beta]$ with $0 < \alpha \le \beta$.
Then
\[
4\alpha\beta \Big(\sum_k w_k\Big)\Big(\sum_k w_k\lambda_k^2\Big)
\;\le\; (\alpha+\beta)^2\Big(\sum_k w_k \lambda_k\Big)^2 .
\]
\end{theorem}

\begin{proof}
Pointwise $(\lambda_k-\alpha)(\beta-\lambda_k)\ge 0$, i.e.
$\lambda_k^2 \le (\alpha+\beta)\lambda_k - \alpha\beta$. With
$S = \sum_k w_k$, $M = \sum_k w_k\lambda_k$, $Q = \sum_k w_k\lambda_k^2$ this
gives $Q \le (\alpha+\beta)M - \alpha\beta S$, whence
\[
(\alpha+\beta)^2M^2 - 4\alpha\beta SQ
\;\ge\; (\alpha+\beta)^2M^2 - 4\alpha\beta S\big((\alpha+\beta)M-\alpha\beta S\big)
\;=\; \big((\alpha+\beta)M - 2\alpha\beta S\big)^2 \;\ge\; 0 . \qedhere
\]
\end{proof}

\begin{theorem}[Sharp seed-imbalance law]\label{thm:sharp}
Let $(u,v)$ have ratio profile $\lambda_k \in [\alpha,\beta]$ with
$0<\alpha\le\beta$, let $E(u)>0$, and suppose $\rho_k \ge \rho \ge 0$ for all
$k$. Then
\[
\rpool(u,v) \;\ge\; \rho\,\kappa(\alpha,\beta),
\qquad
\kappa(\alpha,\beta) := \frac{2\sqrt{\alpha\beta}}{\alpha+\beta}.
\]
\end{theorem}

\begin{proof}
Put $w_k = \norm{u_k}^2$. Then $\ip{u_k}{v_k} = \rho_k \lambda_k w_k \ge
\rho\lambda_k w_k$, so the numerator of $\rpool$ is at least $\rho M$, while the
denominator is $\sqrt{S}\sqrt{Q}$. Theorem~\ref{thm:kant} states exactly that
$2\sqrt{\alpha\beta}\sqrt{S}\sqrt{Q} \le (\alpha+\beta)M$.
\end{proof}

The constant $\kappa$ is the ratio of the geometric to the arithmetic mean of the
window endpoints, equal to $1$ exactly for balanced families.

\begin{theorem}[Sharpness]\label{thm:sharpness}
There is a two-block family with ratio profile in $[1,4]$, per-seed readings
both $1$, and pooled reading exactly $\kappa(1,4) = 4/5$.
\end{theorem}

\begin{theorem}[The sharp constant dominates the crude one]
For $L>0$ and $0<\delta<1$, on the window $[L(1-\delta), L(1+\delta)]$,
\[
\frac{1-\delta}{1+\delta} \;<\; \kappa = \sqrt{1-\delta^2}.
\]
\end{theorem}

\begin{proof}
Here $\alpha\beta = L^2(1-\delta^2)$ and $\alpha+\beta = 2L$, so
$\kappa = \sqrt{1-\delta^2}$. Squaring the claim and clearing denominators
reduces it to $(1+\delta)^3 > 1-\delta$, true for $0<\delta<1$.
\end{proof}

\begin{proposition}[Fixed-weight ladders]
Let $w_k \ge 0$. \emph{(i)} If $\sum_k w_k\rho_k < \sum_k w_k \sigma_k$ then
$\rho_j < \sigma_j$ for some $j$: a pooled rebound at fixed weights is a seed
rebound. \emph{(ii)} If $\sigma_k \le \rho_k$ for all $k$ then
$\sum_k w_k \sigma_k \le \sum_k w_k \rho_k$: seedwise decline forces pooled
decline.
\end{proposition}

\section{Rigidity and stability}

Normalise: $w_k \ge 0$, $\sum_k w_k = 1$, $\lambda_k \in [\alpha,\beta]$,
$M = \sum_k w_k\lambda_k$, $Q = \sum_k w_k \lambda_k^2$. Define the
\emph{Kantorovich slack}
\[
g(w,\lambda) \;=\; (\alpha+\beta)^2M^2 - 4\alpha\beta Q \;\ge\; 0 .
\]

\begin{theorem}[Exact slack identity]\label{thm:slack}
For normalised $w$,
\[
g(w,\lambda) \;=\; \big((\alpha+\beta)M - 2\alpha\beta\big)^2
\;+\; 4\alpha\beta \sum_k w_k(\lambda_k-\alpha)(\beta-\lambda_k).
\]
\end{theorem}

\begin{proof}
Expand $\sum_k w_k(\lambda_k-\alpha)(\beta-\lambda_k) = (\alpha+\beta)M -
\alpha\beta - Q$ using $\sum_k w_k = 1$ and substitute; the result is a
polynomial identity in $M$ and $Q$.
\end{proof}

Both summands are nonnegative: the identity decomposes failure-to-be-extremal
into a \emph{mean defect} and an \emph{endpoint defect}.

\begin{theorem}[Rigidity]\label{thm:rigid}
Let $0<\alpha\le\beta$, $w$ normalised, $\lambda_k \in [\alpha,\beta]$. If
$g(w,\lambda)=0$ then
\begin{enumerate}
\item $w_k(\lambda_k-\alpha)(\beta-\lambda_k) = 0$ for every $k$ (endpoint
support), and
\item $(\alpha+\beta)M = 2\alpha\beta$: the mean equals the harmonic mean of the
window.
\end{enumerate}
\end{theorem}

\begin{proof}
Two nonnegative quantities summing to zero both vanish; the second is a sum of
nonnegative terms, so each term vanishes.
\end{proof}

\begin{theorem}[Uniqueness of the extremal distribution]\label{thm:mass}
If moreover $\alpha < \beta$ and $g(w,\lambda) = 0$, then
\[
\sum_{k:\,\lambda_k=\alpha} w_k = \frac{\beta}{\alpha+\beta},
\qquad
\sum_{k:\,\lambda_k=\beta} w_k = \frac{\alpha}{\alpha+\beta}.
\]
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:rigid}(1) every $k$ with $w_k>0$ has
$\lambda_k \in \{\alpha,\beta\}$. If $A$ is the mass at $\alpha$ then
$M = A\alpha + (1-A)\beta$, and Theorem~\ref{thm:rigid}(2) becomes a linear
equation in $A$ with nonzero coefficient (as $\alpha<\beta$), solved by
$A = \beta/(\alpha+\beta)$.
\end{proof}

\begin{theorem}[The extremiser exists]
For every $0<\alpha\le\beta$ the two-point profile $\lambda = (\alpha,\beta)$,
$w = (\beta/(\alpha+\beta), \alpha/(\alpha+\beta))$ has $g(w,\lambda) = 0$.
\end{theorem}

\begin{proof}
$M = 2\alpha\beta/(\alpha+\beta)$ and $Q = \alpha\beta$, so
$(\alpha+\beta)^2M^2 = 4\alpha^2\beta^2 = 4\alpha\beta Q$.
\end{proof}

\begin{theorem}[Strictness from one interior seed]\label{thm:strict}
If some $j$ has $w_j > 0$ and $\alpha < \lambda_j < \beta$, then
$g(w,\lambda) > 0$.
\end{theorem}

\begin{proof}
Otherwise Theorem~\ref{thm:rigid}(1) would force
$w_j(\lambda_j - \alpha)(\beta-\lambda_j) = 0$, contradicting positivity of all
three factors.
\end{proof}

A real seed profile is never perfectly polarised at the endpoints of the ratio
window, hence never suffers the worst-case attenuation.

\begin{lemma}[Endpoint convexity estimate]\label{lem:endpoint}
For $\alpha \le \lambda \le \beta$,
\[
\frac{\beta-\alpha}{2}\min(\lambda-\alpha, \beta-\lambda)
\;\le\; (\lambda-\alpha)(\beta-\lambda).
\]
\end{lemma}

\begin{theorem}[Stability]\label{thm:stab}
Let $0<\alpha<\beta$, $w$ normalised, $\lambda_k \in [\alpha,\beta]$, and
$g(w,\lambda) \le \varepsilon$. Then
\[
\sum_k w_k \dist(\lambda_k, \{\alpha,\beta\})
\;\le\; \frac{\varepsilon}{2\alpha\beta(\beta-\alpha)},
\qquad
\big((\alpha+\beta)M - 2\alpha\beta\big)^2 \le \varepsilon .
\]
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:slack} each summand is at most $\varepsilon$; the second
statement is immediate, and for the first, Lemma~\ref{lem:endpoint} replaces each
product $(\lambda_k-\alpha)(\beta-\lambda_k)$ by $\frac{\beta-\alpha}{2}$ times
the distance to the nearer endpoint.
\end{proof}

\begin{corollary}[Mean-defect form]
$\big|M - 2\alpha\beta/(\alpha+\beta)\big| \le \sqrt{\varepsilon}/(\alpha+\beta)$.
\end{corollary}

\begin{corollary}[Stability recovers rigidity]
Setting $\varepsilon = 0$ in Theorem~\ref{thm:stab} gives
$w_k \dist(\lambda_k,\{\alpha,\beta\}) = 0$ for all $k$, the endpoint half of
Theorem~\ref{thm:rigid}. The estimate is therefore sharp at the extremiser.
\end{corollary}

\section{Noise versus signal on a ladder}

\begin{lemma}[Pooled values inherit the seed window]\label{lem:window}
If $w_k \ge 0$, $\sum_k w_k = 1$ and $\ell \le \rho_k \le \ell+s$ for all $k$,
then $\ell \le \sum_k w_k\rho_k \le \ell+s$.
\end{lemma}

\begin{theorem}[A sub-spread step carries no information]\label{thm:noise}
For every $t$ with $0 \le t \le s$ there are two weightings and two seed
families, both inside a single common window of width $s$, whose pooled values
differ by exactly $t$.
\end{theorem}

\begin{proof}
Common window $[0,s]$, weights $(1,0)$ in both cases, readings $(t,t)$ and
$(0,0)$.
\end{proof}

\begin{theorem}[Two-spread criterion]\label{thm:twospread}
Let two pooled values arise, with normalised weights, from seed families in
windows $[\ell,\ell+s]$ and $[\ell',\ell'+s]$. If the difference of pooled values
exceeds $s$ then $\ell' < \ell$; if it exceeds $2s$ then every reading of the
second family is strictly below every reading of the first.
\end{theorem}

\begin{remark}[Application to the record]
With seed spread $s = 0.082$: the rebound $+0.0226$ and its retrace $-0.0483$
both satisfy $|\text{step}| \le s$, so by Theorem~\ref{thm:noise} each is
realisable inside a single unchanged seed window and is not evidence of any
change; the cumulative decline $0.5739 - 0.4364 = 0.1375 > s$, so by
Theorem~\ref{thm:twospread} the top and bottom of the ladder cannot share a seed
window. The rebound is noise; the trend is signal.
\end{remark}

\section{Capacity--fade duality}\label{sec:cap}

If $u_1,\dots,u_k$ are mutually decorrelated (orthonormal) and each reads at
least $\rho \ge 0$ against a unit response $w$, then Bessel's inequality gives
$k\rho^2 \le 1$: high readings are a scarce resource.

\begin{definition}[Capacity of a reading]
$\cpc(\rho) = \lfloor 1/\rho^2 \rfloor$, the largest $k$ permitted by
$k\rho^2 \le 1$.
\end{definition}

\begin{proposition}[Antitonicity]
If $0 < \rho \le \sigma$ then $\cpc(\sigma) \le \cpc(\rho)$: a fading dial has
nondecreasing capacity.
\end{proposition}

\begin{lemma}[Small reading, large capacity]\label{lem:conv1}
If $\rho > 0$ and $\rho \le 1/(K+1)$ for $K \in \mathbb{N}$, then
$K \le \cpc(\rho)$.
\end{lemma}

\begin{proof}
From $\rho(K+1) \le 1$ we get $K\rho^2 \le (K+1)\rho^2 \le \rho \le 1$, hence
$K \le 1/\rho^2$, and $K$ is an integer.
\end{proof}

\begin{lemma}[Large capacity, small reading]
If $K \ge 1$, $\rho>0$ and $K \le \cpc(\rho)$, then $\rho^2 \le 1/K$.
\end{lemma}

\begin{definition}[Persistent multiplicative fade]
A ladder $(\rho_k)_{k\ge0}$ of positive readings \emph{fades at rate $q$} if
$0 \le q < 1$ and $\rho_{k+1} \le q\rho_k$ for all $k$.
\end{definition}

\begin{lemma}[Geometric envelope]\label{lem:geo}
A ladder fading at rate $q$ satisfies $\rho_k \le q^k\rho_0$; consequently for
every $\varepsilon>0$ there is $N$ with $\rho_k < \varepsilon$ for all $k \ge N$.
\end{lemma}

\begin{theorem}[Fade implies unbounded capacity]\label{thm:capfade}
If $(\rho_k)$ is positive and fades at rate $q<1$, then for every
$K \in \mathbb{N}$ there is $N$ with $K \le \cpc(\rho_N)$.
\end{theorem}

\begin{proof}
Apply Lemma~\ref{lem:geo} with $\varepsilon = 1/(K+1)$, then
Lemma~\ref{lem:conv1}.
\end{proof}

\begin{theorem}[Capacity ceiling is a positive floor]\label{thm:capfloor}
If $(\rho_k)$ is positive and $\cpc(\rho_N) \le K$ for every $N$, then
$\rho_N^2 > 1/(K+1)$ for every $N$.
\end{theorem}

\begin{proof}
$1/\rho_N^2 < \lfloor 1/\rho_N^2\rfloor + 1 = \cpc(\rho_N)+1 \le K+1$; rearrange.
\end{proof}

Theorems~\ref{thm:capfade} and \ref{thm:capfloor} are the
\emph{capacity--fade duality}: for a positive ladder, having a positive floor is
\emph{equivalent} to having bounded capacity. The floor hypothesis is not a
weakening of the fade law but its exact negation, expressed in the dual language
of decorrelated families.

\begin{remark}[The record in capacity terms]
$\cpc(0.5739) = \lfloor 3.0362\rfloor = 3$ and
$\cpc(0.43636) = \lfloor 5.2518 \rfloor = 5$, so the recorded ladder is a strict
capacity expansion: at the top of the ladder at most three mutually decorrelated
statistics can all read at the dial level, at the current reading five can. With
the rebound rung removed as noise, the de-noised ladder satisfies
$\rho_{k+1} \le 0.98\rho_k$ at every rung; if that rate persists, five further
rungs put the reading below $0.40$ and the capacity at $6$.
\end{remark}

\section{The advantage--decorrelation duality}

Let $a = \cor(u,w)$, $b = \cor(v,w)$, $c = \cor(u,v)$. Positive
semidefiniteness of the $3\times3$ correlation matrix is the \emph{Gram
condition}
\begin{equation}\label{eq:gram}
a^2+b^2+c^2 \;\le\; 1 + 2abc .
\end{equation}

\begin{theorem}[Ellipse form of Gram positivity]\label{thm:ellipse}
For all real $a,b,c$, \eqref{eq:gram} holds if and only if
$(c-ab)^2 \le (1-a^2)(1-b^2)$, by the identity
\[
1 - a^2 - b^2 - c^2 + 2abc = (1-a^2)(1-b^2) - (c-ab)^2 .
\]
\end{theorem}

\begin{corollary}[Ellipse certificate]
Under \eqref{eq:gram}, $c \le ab + \sqrt{(1-a^2)(1-b^2)}$.
\end{corollary}

\begin{theorem}[Advantage bounds decorrelation]\label{thm:adv}
Under \eqref{eq:gram} with $a^2, b^2 \le 1$ and $-1 \le c \le 1$,
\[
(a-b)^2 \le 2(1-c), \qquad c \le 1 - \tfrac12(a-b)^2, \qquad
a - b \le \sqrt{2(1-c)} .
\]
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:ellipse} and AM--GM,
$c \le ab + \sqrt{(1-a^2)(1-b^2)} \le ab + \frac{(1-a^2)+(1-b^2)}{2}
= 1 - \frac{(a-b)^2}{2}$. The degenerate case $c=-1$ forces $a=-b$, where
$(a-b)^2 = 4a^2 \le 4 = 2(1-c)$.
\end{proof}

Any measured advantage is therefore a certificate of decorrelation: two
statistics reading very differently against the same response cannot be nearly
the same statistic.

\begin{theorem}[Sharpness in $c$ alone]
For every $-1 \le c < 1$ there are unit $u,v$ and nonzero $w$ in $\mathbb{R}^2$
with $\cor(u,v) = c$ and $\cor(u,w) - \cor(v,w) = \sqrt{2(1-c)}$.
\end{theorem}

\begin{theorem}[The ellipse certificate always dominates]\label{thm:dominates}
For $a^2,b^2 \le 1$,
\[
ab + \sqrt{(1-a^2)(1-b^2)} \;\le\; 1 - \tfrac12(a-b)^2 ,
\]
with equality precisely when $|a| = |b|$.
\end{theorem}

Thus the advantage certificate is exactly the AM--GM relaxation of the ellipse
certificate: sharp when only the gap is known, strictly lossy once both readings
are known and $|a| \ne |b|$. At the recorded readings $a = 0.43636$ (statistic
$T$) and $b = 0.36116$ (count baseline), the advantage certificate gives
$c \le 1 - 0.0752^2/2 = 0.99717248$, whereas the ellipse certificate gives
$c \le 0.9967$.

\section{The inverse pooling problem}

\begin{theorem}[Inverse pooling law]\label{thm:inverse}
Let $(u,v)$ have ratio profile $\lambda_k \in [\alpha,\beta]$ with
$0<\alpha\le\beta$, and suppose $\rho_{\min} \le \rho_k \le \rho_{\max}$ with
$\rho_{\min}, \rho_{\max} \ge 0$. Then
\[
\rpool \;\le\; \rho_{\max}
\qquad\text{and}\qquad
\rho_{\min} \;\le\; \rpool \cdot \frac{\alpha+\beta}{2\sqrt{\alpha\beta}} .
\]
\end{theorem}

\begin{proof}
The first inequality is Corollary~\ref{cor:noinfl}; the second is
Theorem~\ref{thm:sharp} with $\rho = \rho_{\min}$, divided by
$\kappa(\alpha,\beta)>0$.
\end{proof}

\begin{corollary}[The recorded window]
If the seed ratios lie in $[1,1.21]$ and the pooled reading is $0.43636$, then
some seed reads at least $0.43636$ and some seed reads at most $0.43835$.
\end{corollary}

\begin{proof}
$\sqrt{\alpha\beta} = 1.1$, so $1/\kappa = 2.21/2.2$ and
$0.43636 \times 2.21/2.2 = 0.438344\ldots \le 0.43835$.
\end{proof}

\section{The fade is seedwise}

\begin{theorem}[The recorded step is not an imbalance artefact]\label{thm:notartefact}
If the per-seed ratios lie in $[1,1.21]$ and every seed reads at least the
previous rung's value $0.4847$, then $\rpool > 0.43636$.
\end{theorem}

\begin{proof}
Theorem~\ref{thm:sharp} with $\alpha=1$, $\beta=1.21$, $\rho = 0.4847$ gives
$\rpool \ge 0.4847 \times 2.2/2.21 = 0.482507\ldots > 0.43636$.
\end{proof}

So the observed value was unreachable inside the recorded imbalance window unless
the seeds themselves declined: the $-0.0483$ step is a genuine seedwise decline.
Likewise, a pooled reading of $0.43636$ inside that window forces every seed to
read below $0.5739$.

\begin{theorem}[How wide the window would have to be]
To explain the fall from $0.4847$ to $0.43636$ by imbalance alone one needs
$\kappa(\alpha,\beta) \le 0.9003$, hence $\beta/\alpha \ge 2.54$ (in particular
$\beta \ge 1.9\alpha$); to explain the whole decline from $0.5739$ one needs
$\kappa \le 0.76035$, hence $\beta/\alpha \ge 4.71$, a nearly five-fold
imbalance.
\end{theorem}

Both thresholds lie far outside the recorded seed behaviour and both are
falsifiable by measuring the per-seed norms.

\section{Algorithms}

\subsection*{Pooled correlation from block data}
Compute $N = \sum_k \ip{u_k}{v_k}$, $E_u = \sum_k \norm{u_k}^2$,
$E_v = \sum_k \norm{v_k}^2$ and return $N/\sqrt{E_uE_v}$. Cost $\Theta(mn)$. The
same pass yields the per-seed readings, the ratio profile, the imbalance window
$[\min_k\lambda_k, \max_k\lambda_k]$, and all certified bounds.

\subsection*{Certified seed window from a pooled value}
Given $\rpool$ and $[\alpha,\beta]$, compute
$\kappa = 2\sqrt{\alpha\beta}/(\alpha+\beta)$ and return
$[\rpool, \rpool/\kappa]$ as in Theorem~\ref{thm:inverse}. Cost $\Theta(1)$.

\subsection*{Capacity ladder and floor test}
Compute $\cpc(\rho_k) = \lfloor 1/\rho_k^2\rfloor$ per rung and
$q = \max_k \rho_{k+1}/\rho_k$. If $q<1$, no positive floor is consistent with
the fade continuing, and reaching capacity $K$ requires
$\lceil \log(1/((K+1)\rho_{\text{last}}))/\log q\rceil$ further rungs.
Conversely an observed capacity ceiling $K$ certifies the floor $1/\sqrt{K+1}$.
Cost linear in the number of rungs.

\section{Discussion}

